{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.packing_report AS SELECT w.marketplace_mapped, w.packing_user, w.packed_time, w.order_name, w.saleorderitemcode, p.\"Picklist Code\", pc.PACKER_NAME, bp.\"PACKER NAME\" as b2b_packer, w.warehouse_name, CASE WHEN EXTRACT(HOUR FROM packed_time) BETWEEN 8 AND 19 THEN \'Day\' ELSE \'Night\' END AS shift_type, CASE WHEN EXTRACT(HOUR FROM w.packed_time) < 8 THEN DATEADD(DAY, -1, w.packed_time::DATE) ELSE w.packed_time::DATE END AS adjusted_date FROM snitch_db.maplemonk.warehouse_sla_performance w LEFT JOIN snitch_db.maplemonk.unicommerce_get_picklist p ON w.saleorderitemcode = p.\"Sale Order Item Code\" LEFT JOIN snitch_db.maplemonk.pickpack_cleanup2 pc ON p.\"Picklist Code\" = pc.\"PICKLIST ID\" left join snitch_db.maplemonk.gs_b2b_picknpack bp on p.\"Picklist Code\" = bp.\"PICKLIST ID\" WHERE w.packed_time IS NOT NULL and w.packed_time::DATE >= current_date - 60 and warehouse_name like \'%WH%\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.rto_report AS WITH ranked_data AS ( SELECT *, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\')) BETWEEN 8 AND 19 THEN \'Day\' ELSE \'Night\' END AS shift_type, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\')) < 8 THEN DATEADD(DAY, -1, CAST(TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\') AS DATE)) ELSE CAST(TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\') AS DATE) END AS adjusted_date, ROW_NUMBER() OVER ( PARTITION BY \"Sale Order Item\" ORDER BY TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\') DESC ) AS row_num FROM snitch_db.maplemonk.snitch_db_get_courier_returns_itemwise_new WHERE \"Return Date\"::date >= current_date - 90 ) SELECT d.*, gs.\"UC Username\" FROM ranked_data d left join snitch_db.maplemonk.gs_mapping gs on d.\"Putaway User Id\" = gs.email WHERE row_num = 1; CREATE OR REPLACE TABLE snitch_db.maplemonk.dto_report AS WITH ranked_data AS ( SELECT *, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\')) BETWEEN 8 AND 19 THEN \'Day\' ELSE \'Night\' END AS shift_type, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\')) < 8 THEN DATEADD(DAY, -1, CAST(TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\') AS DATE)) ELSE CAST(TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\') AS DATE) END AS adjusted_date, ROW_NUMBER() OVER ( PARTITION BY \"Sale Order Item Code\" ORDER BY TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\') DESC ) AS row_num FROM snitch_db.maplemonk.snitch_get_copy_of_reverse_pickup WHERE \"Reverse Pickup Last Updated\"::date >= current_date - 90 AND \"Warehouse Name\" LIKE \'%WH%\' ) SELECT d.*, gs.\"UC Username\" FROM ranked_data d left join snitch_db.maplemonk.gs_mapping gs on d.\"Putaway Created By\" = gs.email WHERE row_num = 1; CREATE OR REPLACE TABLE snitch_db.maplemonk.manifestdetailed_report AS WITH shipping_manifest AS ( SELECT *, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\')) BETWEEN 8 AND 19 THEN \'Day\' ELSE \'Night\' END AS shift_type, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\')) < 8 THEN DATEADD(DAY, -1, CAST(TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\') AS DATE)) ELSE CAST(TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\') AS DATE) END AS adjusted_date FROM snitch_db.maplemonk.unicommerce_get_shipping_manifest_by_item WHERE CAST(created AS DATE) >= current_date - 90 and \"Warehouse Name\" like \'%WH%\' ), ranked_manifest AS ( SELECT sm.*, u.marketplace_mapped, u.order_timestamp, ROW_NUMBER() OVER ( PARTITION BY CONCAT(sm.\"Order Number\", sm.\"Shipping Package Code\") ORDER BY sm.UPDATED DESC ) AS row_num FROM shipping_manifest AS sm LEFT JOIN snitch_db.maplemonk.warehouse_sla_performance AS u ON sm.\"Order Number\" = u.order_name AND CAST(u.order_timestamp AS DATE) >= current_date - 90 ) SELECT * FROM ranked_manifest WHERE row_num = 1 ; CREATE OR REPLACE TABLE snitch_db.maplemonk.pickpack_cleanup AS SELECT \"PICKLIST ID\", DATE, QNTY, SHIFT, \"ORDER COUNT\", \"MP\'s Channel\", LEFT(\"PACKER NAME\", POSITION(\'#\' IN \"PACKER NAME\") - 1) AS PACKER_NAME, LEFT(\"PICKER NAME\", POSITION(\'#\' IN \"PICKER NAME\") - 1) AS PICKER_NAME FROM snitch_db.maplemonk.gs_picknpack; CREATE OR REPLACE TABLE snitch_db.maplemonk.pickpack_cleanup2 AS SELECT \"PICKLIST ID\", MAX(DATE) AS DATE, MAX(QNTY) AS QNTY, MAX(SHIFT) AS SHIFT, MAX(\"ORDER COUNT\") AS \"ORDER COUNT\", COALESCE(NULLIF(MAX(\"PACKER_NAME\"), \'\'), NULLIF(MIN(\"PACKER_NAME\"), \'\')) AS PACKER_NAME, COALESCE(NULLIF(MAX(\"PICKER_NAME\"), \'\'), NULLIF(MIN(\"PICKER_NAME\"), \'\')) AS PICKER_NAME FROM snitch_db.maplemonk.pickpack_cleanup GROUP BY \"PICKLIST ID\"; CREATE OR REPLACE TABLE snitch_db.maplemonk.picklist_report AS WITH picklist_cte AS ( SELECT *, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\')) BETWEEN 8 AND 19 THEN \'Day\' ELSE \'Night\' END AS shift_type, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\')) < 8 THEN DATEADD(DAY, -1, CAST(TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\') AS DATE)) ELSE CAST(TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\') AS DATE) END AS adjusted_date FROM snitch_db.maplemonk.unicommerce_get_picklist WHERE created >= current_date - 45 AND \"Warehouse Name\" LIKE \'%WH%\' ), intermediate AS ( SELECT order_id, order_timestamp, marketplace_mapped FROM snitch_db.maplemonk.warehouse_sla_performance WHERE order_date >= current_date - 45 ), ranked_data AS ( SELECT p.*, i.marketplace_mapped, i.order_timestamp, ROW_NUMBER() OVER ( PARTITION BY p.\"Sale Order Item Code\", p.\"Picklist Code\", p.\"Item Status\" ORDER BY p.UPDATED DESC ) AS row_num FROM picklist_cte AS p LEFT JOIN intermediate AS i ON p.\"Sale Order Code\" = i.order_id ), final_join AS ( SELECT d.*, pc.PICKER_NAME, pc.PACKER_NAME, bp.\"PICKER NAME\" as B2C_PICKER FROM ranked_data d LEFT JOIN snitch_db.maplemonk.pickpack_cleanup2 pc ON d.\"Picklist Code\" = pc.\"PICKLIST ID\" left join snitch_db.maplemonk.gs_b2b_picknpack bp on d.\"Picklist Code\" = bp.\"PICKLIST ID\" WHERE d.row_num = 1 ) SELECT * FROM final_join; CREATE OR REPLACE TABLE snitch_db.maplemonk.manifest_report AS select TO_DATE(TRIM(\"DATE\"), \'DD/MM/YYYY\') as \"DATE\", \"Name \", \"Shift \", CAST(SHIPMENTCOUNT as integer) as count from snitch_db.maplemonk.gs_b2c_stickering; create or replace table snitch_db.maplemonk.resticker_report as SELECT TO_DATE(TRIM(\"Date \"), \'DD/MM/YYYY\') AS formatted_date, CAST(MONTH AS INTEGER) AS month, TRIM(\"Name \") AS name, UPPER(TRIM(SHIFT)) AS shift, CAST(\"Re -Stickering Qty\" AS INTEGER) AS manifest_qty FROM snitch_db.maplemonk.gs_b2c_manifest WHERE \"Date \" IS NOT NULL; CREATE OR REPLACE TABLE snitch_db.maplemonk.productivity_calculation AS WITH achieved_data AS ( SELECT putaway_updated::date AS adjusted_date, \'DAY\' AS Shift, SUM(putaway_completed_quantity) AS achieved_inv_consol, \'Inv_consol\' AS team FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(final_type) LIKE \'%activity%\' AND \"Warehouse Name\" IN (\'SAPL-WH2\',\'SAPL-WH1\') GROUP BY adjusted_date, Shift UNION ALL SELECT putaway_updated::date AS adjusted_date, \'DAY\' AS Shift, SUM(putaway_completed_quantity) AS achieved_returns_putaway, \'Returns_Putaway\' AS team FROM snitch_db.maplemonk.putaway_tracking WHERE (LOWER(final_type) LIKE \'%b2c return%\'or LOWER(final_type) LIKE \'%wpr%\') AND \"Warehouse Name\" IN (\'SAPL-WH2\',\'SAPL-WH1\') GROUP BY adjusted_date, Shift UNION ALL SELECT putaway_updated::date AS adjusted_date, \'DAY\' AS Shift, SUM(putaway_completed_quantity) AS achieved_putaway, \'Putaway\' AS team FROM snitch_db.maplemonk.putaway_tracking WHERE (LOWER(final_type) LIKE \'%store%\'or LOWER(final_type) LIKE \'%new%\' or LOWER(final_type) LIKE \'%b2c return%\'or LOWER(final_type) LIKE \'%wpr%\') AND \"Warehouse Name\" IN (\'SAPL-WH2\',\'SAPL-WH1\') GROUP BY adjusted_date, Shift UNION ALL SELECT adjusted_date, UPPER(shift_type) AS Shift, COUNT(distinct \"Shipping Package Code\") AS achieved_b2c_manifest, \'B2C_Manifest\' AS team FROM snitch_db.maplemonk.manifestdetailed_report WHERE \"Warehouse Name\" IN (\'SAPL-WH2\',\'SAPL-WH1\') GROUP BY adjusted_date, UPPER(shift_type) UNION ALL SELECT adjusted_date::date AS adjusted_date, UPPER(shift_type) AS shift_type, COUNT(\"Sale Order Item Code\") AS achieved_b2c_picker, \'B2C_Picker\' AS team FROM snitch_db.maplemonk.picklist_report WHERE marketplace_mapped in (\'SHOPIFY\',\'MYNTRA\',\'FLIPKART\',\'AJIO\',\'AMAZON\') AND \"Warehouse Name\" IN (\'SAPL-WH2\',\'SAPL-WH1\') GROUP BY adjusted_date, UPPER(shift_type) UNION ALL SELECT adjusted_date AS adjusted_date, UPPER(shift_type) AS shift_type, COUNT(\"Sale Order Item Code\") AS achieved_b2b_picker, \'B2B_Picker\' AS team FROM snitch_db.maplemonk.picklist_report WHERE marketplace_mapped not in (\'SHOPIFY\',\'MYNTRA\',\'FLIPKART\',\'AJIO\',\'AMAZON\') AND \"Warehouse Name\" IN (\'SAPL-WH2\',\'SAPL-WH1\') GROUP BY adjusted_date, UPPER(shift_type) UNION ALL SELECT adjusted_date AS adjusted_date, UPPER(shift_type) AS shift_type, COUNT(saleorderitemcode) AS achieved_b2b_packer, \'B2B_Packer\' AS team FROM snitch_db.maplemonk.packing_report WHERE marketplace_mapped not in (\'SHOPIFY\',\'MYNTRA\',\'FLIPKART\',\'AJIO\',\'AMAZON\') AND warehouse_name IN (\'SAPL-WH2\',\'SAPL-WH1\') GROUP BY adjusted_date, UPPER(shift_type) UNION ALL SELECT adjusted_date AS adjusted_date, UPPER(shift_type) AS shift_type, COUNT(saleorderitemcode) AS achieved_b2c_packer, \'B2C_Packer\' AS team FROM snitch_db.maplemonk.packing_report WHERE marketplace_mapped in (\'SHOPIFY\',\'MYNTRA\',\'FLIPKART\',\'AJIO\',\'AMAZON\') AND warehouse_name IN (\'SAPL-WH2\',\'SAPL-WH1\') GROUP BY adjusted_date, UPPER(shift_type) UNION ALL SELECT formatted_date AS adjusted_date, UPPER(shift) AS shift, SUM(MANIFEST_QTY) AS achieved_b2c_restickering, \'B2C_Restickering\' AS team FROM snitch_db.maplemonk.resticker_report GROUP BY formatted_date, UPPER(shift) UNION ALL select CASE WHEN TRY_TO_TIMESTAMP(QC_TIMESTAMP, \'MON DD, YYYY HH12:MI PM\') IS NOT NULL THEN TO_DATE(TO_TIMESTAMP(QC_TIMESTAMP, \'MON DD, YYYY HH12:MI PM\')) WHEN TRY_TO_TIMESTAMP(QC_TIMESTAMP, \'DD-MM-YYYY\') IS NOT NULL THEN TO_DATE(TO_TIMESTAMP(QC_TIMESTAMP, \'DD-MM-YYYY\')) ELSE NULL END AS adjusted_date, \'DAY\' AS shift_type, COUNT(QC_TIMESTAMP) AS achieved_returns_receiving, \'RETURNS_PROCESSING\' AS team from snitch_db.maplemonk.return_2_inwarding_data where qc_status = \'Completed by Agent\' GROUP BY adjusted_date, UPPER(shift_type) UNION ALL select CASE WHEN TRY_TO_TIMESTAMP(SCANNING_DATE, \'MON DD, YYYY HH12:MI PM\') IS NOT NULL THEN TO_DATE(TO_TIMESTAMP(SCANNING_DATE, \'MON DD, YYYY HH12:MI PM\')) WHEN TRY_TO_TIMESTAMP(SCANNING_DATE, \'DD-MM-YYYY\') IS NOT NULL THEN TO_DATE(TO_TIMESTAMP(SCANNING_DATE, \'DD-MM-YYYY\')) ELSE NULL END AS adjusted_date, \'DAY\' AS shift_type, COUNT(SCANNING_DATE) AS achieved_returns_receiving, \'RETURNS_RECEIVING\' AS team from snitch_db.maplemonk.return_2_inwarding_data where scanning_date not in (\'07-04-2025\',\'17-04-2025\',\'08-04-2025\') GROUP BY adjusted_date, UPPER(shift_type) ) SELECT adjusted_date, Shift, TEAM, SUM(achieved_inv_consol) AS \"Achieved_Inv_Consol\" FROM achieved_data GROUP BY adjusted_date, Shift,TEAM; CREATE OR REPLACE TABLE snitch_db.maplemonk.gs_productivity_target_skip AS SELECT TO_DATE(\"DATE\", \'DD/MM/YYYY\')::date AS \"DATE\", \"SHIFT\" AS shift, CAST(\"B2C_PICKER\" AS INTEGER) AS \"B2C_PICKER\", \"B2C_PICKER\" * 800 AS \"T_B2C_Picker\", CAST(\"B2C_PACKER\" AS INTEGER) AS \"B2C_PACKER\", \"B2C_PACKER\" * 1000 AS \"T_B2C_Packer\", CAST(\"B2C_RESTICKERING\" AS INTEGER) AS \"B2C_RESTICKERING\", \"B2C_RESTICKERING\" * 600 AS \"T_B2C_Restickering\", CAST(\"B2C_MANIFEST\" AS INTEGER) AS \"B2C_MANIFEST\", \"B2C_MANIFEST\" * 2000 AS \"T_B2C_Manifest\", CAST(\"B2B_PICKER\" AS INTEGER) AS \"B2B_PICKER\", \"B2B_PICKER\" * 850 AS \"T_B2B_Picker\", CAST(\"B2B_PACKER\" AS INTEGER) AS \"B2B_PACKER\", \"B2B_PACKER\" * 1000 AS \"T_B2B_Packer\", CAST(\"RETURNS_PROCESSING\" AS INTEGER) AS \"RETURNS_PROCESSING\", \"RETURNS_PROCESSING\" * 300 AS \"T_Returns_Processing\", CAST(\"RETURNS_RECEIVING\" AS INTEGER) AS \"RETURNS_RECEIVING\", \"RETURNS_RECEIVING\" * 1500 AS \"T_Returns_Receiving\", CAST(\"PUTAWAY\" AS INTEGER) AS \"PUTAWAY\", \"PUTAWAY\" * 2700 AS \"T_Putaway\", CAST(\"INV_RATIO\" AS INTEGER) AS \"INV_RATIO\", \"INV_RATIO\" * 2000 AS \"T_Inv_Ratio\", CAST(\"INV_AUDIT\" AS INTEGER) AS \"INV_AUDIT\", \"INV_AUDIT\" * 2250 AS \"T_Inv_Audit\", CAST(\"RETURNS_PUTAWAY\" AS INTEGER) AS \"RETURNS_PUTAWAY\", \"RETURNS_PUTAWAY\" * 2700 AS \"T_Returns_Putaway\", CAST(\"INV_CONSOL\" AS INTEGER) AS \"INV_CONSOL\", \"INV_CONSOL\" * 2250 AS \"T_Inv_Consol\", CAST(\"REFURBISHMENT\" AS INTEGER) AS \"REFURBISHMENT\", \"REFURBISHMENT\" * 500 AS \"T_Refurbishment\", CAST(\"RESTICKERING\" AS INTEGER) AS \"RESTICKERING\", \"RESTICKERING\" * 600 AS \"T_Restickering\", \"Remarks B2C\", \"Remarks B2B\", \"Remarks Return\", \"Remarks Inventory\" FROM snitch_db.maplemonk.gs_productivity_target; create or replace table snitch_db.maplemonk.productivity_summary as select a.*, ps1.\"Achieved_Inv_Consol\" AS QTY_B2C_PICKER, ps2.\"Achieved_Inv_Consol\" AS QTY_B2C_PACKER, ps3.\"Achieved_Inv_Consol\" AS QTY_B2B_PICKER, ps4.\"Achieved_Inv_Consol\" AS QTY_B2B_PACKER, ps5.\"Achieved_Inv_Consol\" AS QTY_B2C_MANIFEST, ps6.\"Achieved_Inv_Consol\" AS QTY_B2C_RESTICKERING, ps7.\"Achieved_Inv_Consol\" AS QTY_INV_AUDIT, ps8.\"Achieved_Inv_Consol\" AS QTY_RETURNS_PROCESSING, ps9.\"Achieved_Inv_Consol\" AS QTY_RETURNS_RECEIVING, ps10.\"Achieved_Inv_Consol\" AS QTY_PUTAWAY, ps11.\"Achieved_Inv_Consol\" AS QTY_RETURNS_PUTAWAY, ps12.\"Achieved_Inv_Consol\" AS QTY_INV_CONSOL, ps13.\"Achieved_Inv_Consol\" AS QTY_REFURBISHMENT, ps14.\"Achieved_Inv_Consol\" AS QTY_INV_RATIO, ps15.\"Achieved_Inv_Consol\" AS QTY_RESTICKERING FROM snitch_db.maplemonk.gs_productivity_target_skip a LEFT JOIN snitch_db.maplemonk.productivity_calculation ps1 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2C_PICKER\' = ps1.adjusted_date || UPPER(ps1.\"SHIFT\") || UPPER(ps1.team) AND ps1.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps2 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2C_PACKER\' = ps2.adjusted_date || UPPER(ps2.\"SHIFT\") || UPPER(ps2.team) AND ps2.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps3 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2B_PICKER\' = ps3.adjusted_date || UPPER(ps3.\"SHIFT\") || UPPER(ps3.team) AND ps3.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps4 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2B_PACKER\' = ps4.adjusted_date || UPPER(ps4.\"SHIFT\") || UPPER(ps4.team) AND ps4.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps5 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2C_MANIFEST\' = ps5.adjusted_date || UPPER(ps5.\"SHIFT\") || UPPER(ps5.team) AND ps5.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps6 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'B2C_RESTICKERING\' = ps6.adjusted_date || UPPER(ps6.\"SHIFT\") || UPPER(ps6.team) AND ps6.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps7 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'INV_AUDIT\' = ps7.adjusted_date || UPPER(ps7.\"SHIFT\") || UPPER(ps7.team) AND ps7.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps8 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'RETURNS_PROCESSING\' = ps8.adjusted_date || UPPER(ps8.\"SHIFT\") || UPPER(ps8.team) AND ps8.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps9 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'RETURNS_RECEIVING\' = ps9.adjusted_date || UPPER(ps9.\"SHIFT\") || UPPER(ps9.team) AND ps9.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps10 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'PUTAWAY\' = ps10.adjusted_date || UPPER(ps10.\"SHIFT\") || UPPER(ps10.team) AND ps10.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps11 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'RETURNS_PUTAWAY\' = ps11.adjusted_date || UPPER(ps11.\"SHIFT\") || UPPER(ps11.team) AND ps11.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps12 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'INV_CONSOL\' = ps12.adjusted_date || UPPER(ps12.\"SHIFT\") || UPPER(ps12.team) AND ps12.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps13 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'REFURBISHMENT\' = ps13.adjusted_date || UPPER(ps13.\"SHIFT\") || UPPER(ps13.team) AND ps13.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps14 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'INV_RATIO\' = ps14.adjusted_date || UPPER(ps14.\"SHIFT\") || UPPER(ps14.team) AND ps14.adjusted_date IS NOT NULL LEFT JOIN snitch_db.maplemonk.productivity_calculation ps15 ON a.\"DATE\"::date || UPPER(a.\"SHIFT\") || \'RESTICKERING\' = ps15.adjusted_date || UPPER(ps15.\"SHIFT\") || UPPER(ps15.team) AND ps15.adjusted_date IS NOT NULL;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            